if(!layoutState.value) {
  layoutState.setValue(true)
    return "0.1px auto"
} else {
  if(!buttonState.value) {
    return "0px 1fr"
  } else {
    return "340px 1fr"
  }
}

let elements = expenseCalculationFilter?.ExpensesFinalList.ExpenseRuleAssignment
if (!Array.isArray(elements)) {
  return [];
}

const returnedArray = [];
elements.forEach((element)=>{

  returnedArray.push({
    id: element.id ? element.id : '',
    version: element.version,
    assignmentOrder : element.assignmentOrder ? element.assignmentOrder:'',
    applicants : element.applicants ? element.applicants : false,
    ruleCode: element.expenseRule? element.expenseRule:'',
    name: element.expenseRule ? element.expenseRule.name : '',
    standard: element.expenseRule?.standard ? element.expenseRule?.standard : false,
    company : element.company ? element.company : '',
    orgUnit: element.organizationalUnit ? element.organizationalUnit:'',
    cascading: element.cascading ? element.cascading : false,
    location: element?.siteLocation ? element.siteLocation : '',
    employmentType:element.employmentType ? element.employmentType.translations.length > 0 ? element.employmentType.translations[0].value  : element.employmentType.value : "",
    contractType : element.contractType ?  element.contractType.translations.length > 0 ? element.contractType.translations[0].value  : element.contractType.value : "",
    employee: element.employee ? element.employee : '',
    activeFrom : element.activeFrom ? element.activeFrom : '',
    activeTo : element.activeTo ? element.activeTo : ''
  })
})

return returnedArray.length > 0 ? returnedArray : [];

transformers.script:
function transformString(input) {
  const parts = input.split(':');
  const transformed = parts[2]
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');

  return transformed;
}

return transformString

