  const order = desc ? "DESC_NULLS_LAST" : "ASC_NULLS_LAST";

  const columnMappings = {
    id: {expenseRule: {code: order}},
    Company: { company: {name: order}},
    name:  {expenseRule: {name: order}},
    location: {siteLocation: {name: order}},
    employmentType:  {employmentType : { value: order}},
    contractType:  {contractType : { value: order}},
    employee: {employee:{firstName: order, lastName:order}},
    activeFrom: {activeFrom: order},
    activeTo: {activeTo: order},
    "faf97b10":{expenseRule: {standard: order}},
    orgUnit:{organizationalUnit:{name:order}},
    cascading:{cascading:order},
    assignmentOrder:{assignmentOrder:order}
  };

  return columnMappings[column] || {assignmentOrder:order};
});

return orderByConditions

